import{_ as p,a0 as c,w as r,s as d,ao as i,I as t,x as s,a1 as a,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"Emacs 調試秘籍之 GUD 調試器 | LCTT x X-CMD","titleTemplate":false,"description":"Emacs 調試秘籍之 GUD 調試器 | LCTT (202003) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Emacs 調試秘籍之 GUD 調試器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Emacs 調試秘籍之 GUD 調試器 | LCTT (202003) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202003/20190925 Debugging in Emacs- The Grand Unified Debugger","title":"Emacs 調試秘籍之 GUD 調試器","tag":"202003","desc":""},"relativePath":"202003/20190925 Debugging in Emacs- The Grand Unified Debugger.md","filePath":"[post].md"}'),l={name:"202003/20190925 Debugging in Emacs- The Grand Unified Debugger.md"};function u(m,e,g,f,b,D){const n=c("Link");return r(),d("div",null,[e[15]||(e[15]=i(`<h1 id="emacs-調試秘籍之-gud-調試器" tabindex="-1">Emacs 調試秘籍之 GUD 調試器 <a class="header-anchor" href="#emacs-調試秘籍之-gud-調試器" aria-label="Permalink to “Emacs 調試秘籍之 GUD 調試器”">​</a></h1><p><img src="https://i0.wp.com/opensourceforu.com/wp-content/uploads/2019/09/Screenshot-from-2019-09-25-15-39-46.png?ssl=1" alt=""></p><blockquote><p>本文簡短地對 Emacs 的調試工具 GUD 的特性進行了探索。</p></blockquote><p>如果你是一個 C 或 C++ 開發者，你很可能已經使用過 GDB（GNU 調試器），毫無疑問，它是現今最強大、最無可匹敵的調試器之一。它唯一的缺點就是它基於命令列，雖然仍能提供許多強大的功能，但有時也會具有一些侷限性。這也就是為什麼聰明的人們開始追求整合了編輯器和調試器的<ruby>圖形化<rt> GUI </rt></ruby><ruby>集成開發環境<rt>Integrated Development Environment</rt></ruby>。仍有些開發者堅信使用鼠標會降低工作效率，在 GUI 上用鼠標點～點～點～是來自惡魔的誘惑。</p><p>因為 Emacs 是現今最酷的文本編輯器之一，我將為你展示如何在不碰鼠標且不離開 Emacs 的情況下，實現寫代碼、編譯代碼、調試代碼的過程。</p><p>GUD（LCTT 譯註：全稱<ruby>大統一調試器<rt>Grand Unified Debugger</rt></ruby>，鑑於其縮寫形式更為人熟知，以下全文將使用縮寫替代此全稱）是 Emacs 下的一個<ruby>模式<rt>mode</rt></ruby>，用於在 Emacs 中運行 GDB。它向 GDB 提供了 Emacs 的所有特性，使用户無需離開編輯器就可以對代碼進行調試。</p><h3 id="使用-gud-的前期準備" tabindex="-1">使用 GUD 的前期準備 <a class="header-anchor" href="#使用-gud-的前期準備" aria-label="Permalink to “使用 GUD 的前期準備”">​</a></h3><p>如果你正在使用一個 Linux 機器，很可能你已經安裝了 GDB 和 gcc，接下來就是要確保已經安裝了 Emacs。以下的內容我將假設讀者熟悉 GDB 並且至少用它做過基本的調試。如果你未曾接觸過 GDB，你可以做個快速入門，這些資料在網上隨處可得。</p><p>對於那些 Emacs 新手，我將向你介紹一些基本術語。縱覽整篇文章，你將看到諸如 <code>C-c M-x</code> 等快捷鍵。此處 <code>C</code> 代表 <code>Ctrl</code> 鍵，<code>M</code> 代表 <code>Alt</code> 鍵。<code>C-c</code> 代表 <code>Ctrl</code> 鍵和 <code>c</code> 鍵被同時按下。如果你看到 <code>C-c c</code>，它代表同時按下 <code>Ctrl</code> 鍵和 <code>c</code> 鍵，釋放後緊接着按下 <code>c</code> 鍵。在 Emacs 中，編輯文本的主要區域被稱為<ruby>主緩衝區<rt>main buffer</rt></ruby>，而在 Emacs 窗口下方用於輸入命令的區域被稱為<ruby>迷你緩衝區<rt>mini buffer</rt></ruby>。</p><p>啓動 Emacs，並按下 <code>C-x C-f</code> 來創建一個新文件。Emacs 將提示你輸入一個文件名，此處讓我們將文件命名為 <code>buggyFactorial.cpp</code>。一旦文件打開，輸入如下代碼：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#include&lt;iostream&gt;</span></span>
<span class="line"><span>#include &lt;assert.h&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>int factorial(int num) {</span></span>
<span class="line"><span>  int product = 1;</span></span>
<span class="line"><span>  while(num--) {</span></span>
<span class="line"><span>    product *= num;</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>  return product;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>int main() {</span></span>
<span class="line"><span>  int result = factorial(5);</span></span>
<span class="line"><span>  assert(result == 120);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>使用 <code>C-x C-s</code> 快捷鍵保存文件。文件保存完畢，是時候進行編譯了。按下 <code>M-x</code>，在彈出的<ruby>提示符<rt>prompt</rt></ruby>後輸入 <code>compile</code> 並點擊回車。然後在提示符後，將內容替換為 <code>g++ -g buggyFactorial.cpp</code> 並再次點擊回車。</p><p><img src="https://i1.wp.com/opensourceforu.com/wp-content/uploads/2019/09/Figure_1.png?ssl=1" alt="圖 1: Emacs 迷你緩衝區中編譯命令"></p><p>這將在 Emacs 中開啓另一個緩衝區，顯示編譯的狀態。如果你的代碼輸入沒有錯誤，你將預期得到如圖 2 所示的緩衝區。</p><p><img src="https://i2.wp.com/opensourceforu.com/wp-content/uploads/2019/09/Figure_2.png?ssl=1" alt="圖 2: 編譯狀態"></p><p>要想隱藏編譯緩衝區，首先確保你的光標在編譯緩衝區中（你可以不使用鼠標，而是通過 <code>C-x o</code> 快捷鍵將光標從一個緩衝區移動到另一個），然後按下 <code>C-x 0</code>。下一步就是運行代碼，並觀察是否運行良好。按下 <code>M-!</code> 快捷鍵並在迷你緩衝區的提示符後面輸入 <code>./a.out</code>。</p><p><img src="https://i0.wp.com/opensourceforu.com/wp-content/uploads/2019/09/Figure_3.png?ssl=1" alt="圖 3: 代碼在迷你緩衝區中的輸出"></p><p>你可以看到迷你緩衝區中顯示斷言失敗。很明顯代碼中有錯誤，因為 5 的階乘是 120。那麼讓我們現在開始調試吧。</p><h3 id="使用-gud-調式代碼" tabindex="-1">使用 GUD 調式代碼 <a class="header-anchor" href="#使用-gud-調式代碼" aria-label="Permalink to “使用 GUD 調式代碼”">​</a></h3><p>現在，我們的代碼已經編譯完成，是時候看看到底哪裏出錯了。按下 <code>M-x</code> 快捷鍵並在提示符後輸入 <code>gdb</code>。在接下來的提示符後，輸入 <code>gdb -i=mi a.out</code>。如果一切順利，GDB 會在 Emacs 緩衝區中啓動，你會看到如圖 4 所示的窗口。</p><p><img src="https://i0.wp.com/opensourceforu.com/wp-content/uploads/2019/09/Figure_4.png?ssl=1" alt="圖 4: Emacs 中的 GDB 緩衝區"></p><p>在 <code>gdb</code> 提示符後，輸入 <code>break main</code> 來設置斷點，並輸入 <code>r</code> 來運行程序。程序會開始運行並停在 <code>main()</code> 函數處。</p><p>一旦 GDB 到達了 <code>main</code> 處設置的斷點，就會彈出一個新的緩衝區顯示你正在調試的代碼。注意左側的紅點，正是你設置斷點的位置，同時會有一個小的標誌提示你當前代碼運行到了哪一行。當前，該標誌就在斷點處（如圖 5）。</p><p><img src="https://i1.wp.com/opensourceforu.com/wp-content/uploads/2019/09/Figure_5.png?ssl=1" alt="圖 5: GDB 與代碼顯示在兩個分離的窗口"></p><p>為了調試 <code>factorial</code> 函數，我們需要單步運行。想要達到此目的，你可以在 GBD 提示符使用 GDB 命令 <code>step</code>，或者使用 Emacs 快捷鍵 <code>C-c C-s</code>。還有其它一些快捷鍵，但我更喜歡 GDB 命令。因此我將在本文的後續部分使用它們。</p><p>單步運行時讓我們注意一下局部變量中的階乘值。參考圖 6 來設置在 Emacs 幀中顯示局部變量值。</p><p><img src="https://i1.wp.com/opensourceforu.com/wp-content/uploads/2019/09/Figure_6.png?ssl=1" alt="圖 6: 在 Emacs 中使用獨立幀顯示局部變量"></p><p>在 GDB 提示符中進行單步運行並觀察局部變量值的變化。在循環的第一次迭代中，我們發現了一個問題。此處乘法的結果應該是 5 而不是 4。</p><p>本文到這裏也差不多結束了，讀者可以自行探索發現 GUD 模式這片新大陸。GDB 中的所有命令都可以在 GUD 模式中運行。我將此代碼的修復留給讀者作為一個練習。看看你在調試的過程中，可以做哪一些定製化，來使你的工作流更加簡單和高效。</p><hr>`,30)),t("p",null,[e[1]||(e[1]=s("via: ",-1)),a(n,{href:"https://opensourceforu.com/2019/09/debugging-in-emacs-the-grand-unified-debugger/"},{default:o(()=>[...e[0]||(e[0]=[s("https://opensourceforu.com/2019/09/debugging-in-emacs-the-grand-unified-debugger/",-1)])]),_:1})]),t("p",null,[e[6]||(e[6]=s("作者：",-1)),a(n,{href:"https://opensourceforu.com/author/vineeth-kartha/"},{default:o(()=>[...e[2]||(e[2]=[s("Vineeth Kartha",-1)])]),_:1}),e[7]||(e[7]=s(" 選題：",-1)),a(n,{href:"https://github.com/lujun9972"},{default:o(()=>[...e[3]||(e[3]=[s("lujun9972",-1)])]),_:1}),e[8]||(e[8]=s(" 譯者：",-1)),a(n,{href:"https://github.com/cycoe"},{default:o(()=>[...e[4]||(e[4]=[s("cycoe",-1)])]),_:1}),e[9]||(e[9]=s(" 校對：",-1)),a(n,{href:"https://github.com/wxy"},{default:o(()=>[...e[5]||(e[5]=[s("wxy",-1)])]),_:1})]),t("p",null,[e[12]||(e[12]=s("本文由 ",-1)),a(n,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...e[10]||(e[10]=[s("LCTT",-1)])]),_:1}),e[13]||(e[13]=s(" 原創編譯，",-1)),a(n,{href:"https://linux.cn/"},{default:o(()=>[...e[11]||(e[11]=[s("Linux中國",-1)])]),_:1}),e[14]||(e[14]=s(" 榮譽推出",-1))])])}const E=p(l,[["render",u]]);export{C as __pageData,E as default};
